#include <opencv2/core.hpp>
#include <opencv2/ptcloud.hpp>
#include <iostream>
#include <vector>

int main(){
  try{
    const int W=256,H=256;
    cv::Mat depth(H,W,CV_32F,cv::Scalar(2.0f));
    cv::Matx33f K((float)2.0793828200968182e-21f,0,0,
                 0,(float)2.0793828200968182e-21f,(float)2.079376761645066e-21f,
                 0,0,1);

    // Singular 4x4 cameraPose from issue #29763 / test_tsdf.cpp Volume.issue_29763
    cv::Matx44f cameraPose = cv::Matx44f::eye();
    // Heuristic: construct the same singular pose used by the test.
    // The original test uses a projection that becomes singular on inv(); emulate by setting bottom row to zeros except w.
    // If this mismatch occurs, the probe will not diverge; we will confirm by comparing with the fixed revision signature.
    cameraPose(3,0)=0; cameraPose(3,1)=0; cameraPose(3,2)=0; cameraPose(3,3)=0; // singular

    const float voxelSize=0.5f;
    const float truncDist=0.001f;
    const int res=128;

    cv::Ptr<cv::ptcloud::Volume> vol;
    // Depending on OpenCV version, VolumeType::TSDF may be in ptcloud namespace.
    vol = cv::ptcloud::createVolume(cv::ptcloud::VolumeType::TSDF, cv::Size3i(res,res,res), voxelSize, truncDist);

    vol->integrate(depth, cameraPose, K);

    cv::Mat points, normals;
    vol->fetchPointsNormals(points, normals);
    std::cout << "points_total="<< points.total() << "\n";
    // Also print whether any NaNs exist in raw points array.
    bool anyNaN=false;
    if(points.type()==CV_32F){
      const float* p = points.ptr<float>();
      for(size_t i=0;i<points.total();++i){
        if(!cv::checkRange(cv::Mat(1,1,CV_32F,const_cast<float*>(p+i)))){ anyNaN=true; break; }
      }
    }
    std::cout << "any_points_nan=" << (anyNaN?1:0) << "\n";
    return 0;
  }catch(const cv::Exception& e){
    std::cerr << "opencv_exception:"<< e.what() << "\n";
    return 100;
  }catch(...){
    std::cerr<<"unknown_exception\n";
    return 101;
  }
}
